 [TestMethod]public Task CompanySameInputViewingBaselineAndFinal()=>RunSta(async()=>{
  var root=Environment.GetEnvironmentVariable("KITAO_COMPANY_VIEWING_ROOT");if(root is null){Assert.Inconclusive("Explicit company measurement root required");return;}EnsureTestApplication();Directory.CreateDirectory(root);var inputs=Path.Combine(root,"../owned-inputs");Directory.CreateDirectory(inputs);var paths=new List<string>();
  for(int k=0;k<100;k++){var path=Path.GetFullPath(Path.Combine(inputs,$"owned-{k:D3}.jpg"));if(!File.Exists(path)){var rgb=new byte[1600*1000*3];for(int y=0;y<1000;y++)for(int x=0;x<1600;x++){int i=(y*1600+x)*3;rgb[i]=(byte)((x/7+k)%256);rgb[i+1]=(byte)((y/4+k*3)%256);rgb[i+2]=(byte)((x/13+y/11+k)%256);}var b=BitmapSource.Create(1600,1000,96,96,PixelFormats.Rgb24,null,rgb,4800);var encoder=new JpegBitmapEncoder{QualityLevel=90};encoder.Frames.Add(BitmapFrame.Create(b));using var f=File.Create(path);encoder.Save(f);}paths.Add(path);}
  var rows=new List<object>();foreach(var pair in new[]{("owned100",paths.ToArray()),("companyRaw5",Directory.GetFiles("D:/AI AGENT/PixelTart-TestAssets/CompanyRAW").Order().ToArray())}){
   using var vm=new ReferenceColorWorkspaceViewModel(new Dialogs());var manifest=new List<object>();foreach(var path in pair.Item2){await using var stream=File.OpenRead(path);var hash=Convert.ToHexString(await SHA256.HashDataAsync(stream));var target=new ReferenceTargetItem(path){SourceHash=hash,IsSelected=true};var version=new StudioEditVersion(Guid.NewGuid(),"公司授权/自建输入",DateTimeOffset.UnixEpoch,null,null,hash,null,null,null,ColorStudioMatchEngine.Stable,MatchV4ExecutionMode.Auto){IsOriginal=true,IsMain=true};target.ActiveEditVersionId=version.Id;target.EditVersions.Add(version);vm.Targets.Add(target);manifest.Add(new{path,sha256=hash,bytes=new FileInfo(path).Length});}vm.PinSelectedViewingVariants();var watch=Stopwatch.StartNew();double? first=null;vm.PropertyChanged+=(_,e)=>{if(e.PropertyName==nameof(vm.ViewingFrames)&&vm.ViewingFrames.Count>0&&first is null)first=watch.Elapsed.TotalMilliseconds;};long peakWs=0,peakPrivate=0,peakManaged=0;using var sampling=new CancellationTokenSource();var sample=Task.Run(async()=>{while(!sampling.IsCancellationRequested){using var process=Process.GetCurrentProcess();peakWs=Math.Max(peakWs,process.WorkingSet64);peakPrivate=Math.Max(peakPrivate,process.PrivateMemorySize64);peakManaged=Math.Max(peakManaged,GC.GetTotalMemory(false));try{await Task.Delay(20,sampling.Token);}catch(OperationCanceledException){}}});await Prepare(vm);var all=watch.Elapsed.TotalMilliseconds;foreach(var frame in vm.ViewingFrames){if(pair.Item1!="companyRaw5")continue;var pngOutput=new PngBitmapEncoder();pngOutput.Frames.Add(BitmapFrame.Create(frame.Image));using var imageFile=File.Create(Path.Combine(root,vm.Targets.Single(t=>t.Id==frame.Item.TargetId).FileName+"-proxy.png"));pngOutput.Save(imageFile);}var imageHashes=vm.ViewingFrames.Select(f=>new{path=vm.Targets.Single(t=>t.Id==f.Item.TargetId).Path,hash=Pixels(f.Image)}).ToArray();var hashReads=vm.GetType().GetProperty("ViewingHashReads",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance)?.GetValue(vm);var decodeCount=vm.GetType().GetProperty("ViewingDecodeCount",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance)?.GetValue(vm);var loaded=vm.ViewingFrames.Count;var failures=vm.ViewingFailures.ToArray();var table=new StudioViewingTableView(vm);watch.Restart();table.Measure(new Size(1200,800));table.Arrange(new Rect(0,0,1200,800));table.UpdateLayout();var initialLayout=watch.Elapsed.TotalMilliseconds;watch.Restart();await table.RefreshAsync();table.UpdateLayout();var refresh=watch.Elapsed.TotalMilliseconds;watch.Restart();var rendered=new RenderTargetBitmap(1200,800,96,96,PixelFormats.Pbgra32);rendered.Render(table);var render=watch.Elapsed.TotalMilliseconds;var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(rendered));using(var f=File.Create(Path.Combine(root,pair.Item1+"-OFFSCREEN.png")))png.Save(f);var controls=Count(table);using var cancel=new CancellationTokenSource();watch.Restart();var pending=Prepare(vm,cancel.Token);cancel.Cancel();await pending;var cancelMs=watch.Elapsed.TotalMilliseconds;sampling.Cancel();await sample;rows.Add(new{imageHashes,hashReads,decodeCount,kind=pair.Item1,requested=pair.Item2.Length,loaded,failures,firstFrameMs=first,allCompleteMs=all,initialLayoutMs=initialLayout,warmControlRefreshMs=refresh,actualControlRenderMs=render,visualCount=controls,cancelMs,peakSampledWorkingSet=peakWs,peakSampledPrivateBytes=peakPrivate,peakSampledManagedBytes=peakManaged,nativeAndRuntimeEstimateBytes=Math.Max(0,peakPrivate-peakManaged),nativeEstimateCaveat="private minus managed samples is an estimate, not allocator-specific native peak",cacheBytes=vm.ViewingCacheBytes,manifest});table.Close();Assert.AreEqual(0,vm.ViewingCacheBytes);await File.WriteAllTextAsync(Path.Combine(root,"MEASUREMENTS.json"),JsonSerializer.Serialize(rows,new JsonSerializerOptions{WriteIndented=true}));
  }
 });

 [TestMethod]public Task ActualColdControlFirstScreenAndCancellation()=>RunSta(async()=>{
  var root=Environment.GetEnvironmentVariable("KITAO_COMPANY_VIEWING_ROOT");if(root is null){Assert.Inconclusive("Explicit company root required");return;}EnsureTestApplication();Directory.CreateDirectory(root);using var vm=new ReferenceColorWorkspaceViewModel(new Dialogs());foreach(var path in Directory.GetFiles(Path.GetFullPath(Path.Combine(root,"../owned-inputs")),"*.jpg").Order().Take(100)){var hash=Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(path)));var target=new ReferenceTargetItem(path){SourceHash=hash,IsSelected=true};var version=new StudioEditVersion(Guid.NewGuid(),"owned",DateTimeOffset.UnixEpoch,null,null,hash,null,null,null,ColorStudioMatchEngine.Stable,MatchV4ExecutionMode.Auto){IsOriginal=true};target.ActiveEditVersionId=version.Id;target.EditVersions.Add(version);vm.Targets.Add(target);}Assert.AreEqual(100,vm.Targets.Count);vm.PinSelectedViewingVariants();var watch=Stopwatch.StartNew();var table=new StudioViewingTableView(vm);table.Measure(new Size(1200,800));table.Arrange(new Rect(0,0,1200,800));table.UpdateLayout();var placeholders=table.GetType().GetProperty("RealizedCardCount",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance)?.GetValue(table);var firstLayout=watch.Elapsed.TotalMilliseconds;double? firstFrame=null;vm.PropertyChanged+=(_,e)=>{if(e.PropertyName==nameof(vm.ViewingFrames)&&vm.ViewingFrames.Count>0&&firstFrame is null){table.UpdateLayout();var b=new RenderTargetBitmap(1200,800,96,96,PixelFormats.Pbgra32);b.Render(table);firstFrame=watch.Elapsed.TotalMilliseconds;}};await table.RefreshAsync();table.UpdateLayout();var all=watch.Elapsed.TotalMilliseconds;var realized=table.GetType().GetProperty("RealizedCardCount",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance)?.GetValue(table);var final=new RenderTargetBitmap(1200,800,96,96,PixelFormats.Pbgra32);watch.Restart();final.Render(table);var renderMs=watch.Elapsed.TotalMilliseconds;var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(final));using(var f=File.Create(Path.Combine(root,"cold-control-OFFSCREEN.png")))encoder.Save(f);table.Close();await File.WriteAllTextAsync(Path.Combine(root,"CONTROL.json"),JsonSerializer.Serialize(new{firstLayoutMs=firstLayout,placeholderCardCount=placeholders,firstActualFrameAndRenderMs=firstFrame,allCompleteWithProgressRenderingMs=all,finalRealizedCardCount=realized,actualFinalControlRenderMs=renderMs,scope="actual WPF offscreen control, not physical pointer FPS"},new JsonSerializerOptions{WriteIndented=true}));
 });

 [TestMethod]public Task NativeDecodeRepeatabilityAndExactProxyExtraction()=>RunSta(async()=>{
  var root=Environment.GetEnvironmentVariable("KITAO_COMPANY_VIEWING_ROOT");if(root is null){Assert.Inconclusive("Explicit company root required");return;}EnsureTestApplication();var decoder=new RAWSelectionAssistant.Core.Services.RawToJpeg.LibRawDecoder();var rows=new List<object>();foreach(var name in new[]{"DSCF0347.RAF","DSCF0370.RAF","TNAN8886.CR3"}){var path="D:/AI AGENT/PixelTart-TestAssets/CompanyRAW/"+name;var first=await decoder.DecodeViewingProxyAsync(path,640);var second=await decoder.DecodeViewingProxyAsync(path,640);var a=first.Rgb48Pixels!;var b=second.Rgb48Pixels!;var differences=a.Zip(b,(x,y)=>Math.Abs(x-y)).ToArray();rows.Add(new{name,max16=differences.Max(),different=differences.Count(x=>x!=0),mean16=differences.Average(),scope="same unchanged native settings; two independent decodes, not mathematical transform error"});}await File.WriteAllTextAsync(Path.Combine(root,"NATIVE_REPEATABILITY.json"),JsonSerializer.Serialize(rows,new JsonSerializerOptions{WriteIndented=true}));
 });

 [TestMethod]public Task HistoricalRawRepeatabilityUsesUnchangedFullDecoder()=>RunSta(async()=>{
  var root=Environment.GetEnvironmentVariable("KITAO_COMPANY_VIEWING_ROOT");if(root is null){Assert.Inconclusive("Explicit company root required");return;}EnsureTestApplication();var pipeline=new RawMatchTiff16ProductPipeline(new RAWSelectionAssistant.Core.Services.RawToJpeg.LibRawDecoder());var rows=new List<object>();foreach(var name in new[]{"DSCF0347.RAF","DSCF0370.RAF"}){async Task<float[]> Decode(){using var full=await pipeline.DecodeMasterAsync("D:/AI AGENT/PixelTart-TestAssets/CompanyRAW/"+name);using var proxy=pipeline.PreviewMaster(full,640);return proxy.Rgb32.ToArray();}var a=await Decode();var b=await Decode();var diff=a.Zip(b,(x,y)=>Math.Abs((double)x-y)).ToArray();rows.Add(new{name,maxFloat=diff.Max(),different=diff.Count(x=>x!=0),meanFloat=diff.Average(),scope="historical full-master decoder repeated twice, no viewing-specific extraction"});}await File.WriteAllTextAsync(Path.Combine(root,"HISTORICAL_REPEATABILITY.json"),JsonSerializer.Serialize(rows,new JsonSerializerOptions{WriteIndented=true}));
 });
 static Task Prepare(ReferenceColorWorkspaceViewModel vm,CancellationToken token=default)=>(Task)vm.GetType().GetMethod("PrepareViewingTableAsync",new[]{typeof(CancellationToken)})!.Invoke(vm,[token])!;
 static string Pixels(BitmapSource image){var converted=new FormatConvertedBitmap(image,PixelFormats.Bgra32,null,0);var rgb=new byte[converted.PixelWidth*converted.PixelHeight*4];converted.CopyPixels(rgb,converted.PixelWidth*4,0);return Convert.ToHexString(SHA256.HashData(rgb));}
 static int Count(DependencyObject d){int n=1;for(int i=0;i<VisualTreeHelper.GetChildrenCount(d);i++)n+=Count(VisualTreeHelper.GetChild(d,i));return n;}
 internal sealed class Dialogs:IDialogService{public IReadOnlyList<string> ChooseFiles(string a,string b,bool c)=>[];public string? ChooseFolder(string a,string? b=null)=>null;public string? ChooseSaveFile(string a,string b,string c,string? d=null)=>null;public bool Confirm(string a,string b)=>false;public void ShowInfo(string a){}public void ShowError(string a){}public IReadOnlyList<string>? ManageQuickTools(IReadOnlyList<string>x)=>x;public HelpAction ShowHelp()=>HelpAction.None;public void ShowFeedback(){}public RAWSelectionAssistant.Core.Models.RawFileEntry? ChooseRawCandidate(IReadOnlyList<RAWSelectionAssistant.Core.Models.RawFileEntry>x)=>null;public bool ShowMediaDetails(RAWSelectionAssistant.Core.Models.MediaSelectionItem x,bool y)=>false;public void RevealFile(string p){}}
